using System;using System.Linq;using IdleIntelligence.Core;using UnityEngine;using UnityEngine.UI;
namespace IdleIntelligence.Runtime
{
 public sealed class MetaLabView:MonoBehaviour
 {
  public Sprite Mira,ModelArt;GameRuntime game;Text ledger;Transform rows;string signature="";PrestigePulse pulse;
  public void Initialize(GameRuntime runtime){game=runtime;ledger=WorkshopUIFactory.Label("KnowledgeLedger",transform,"",18,100);rows=WorkshopUIFactory.Vertical("Models",transform).transform;pulse=Instantiate(game.PrestigePrefab.Pulse,GetComponentInParent<Canvas>().transform);WorkshopUIFactory.Fill((RectTransform)pulse.transform);pulse.gameObject.AddComponent<SafeArea>();pulse.Core.GetComponent<Image>().sprite=ModelArt;Refresh();}
  void Update(){if(game!=null)Refresh();}
  void Refresh(){var s=game.State;ledger.text="GEHEIMES LABOR\nErkenntnis "+ScientificNumber.FromData(s.Prestige.knowledge)+" · +"+PrestigeRules.KnowledgeRate(s)+"/s\nAktiv: "+(string.IsNullOrEmpty(s.Workshop.activeModel)?"keines":MetaBalance.Models.First(m=>m.Id==s.Workshop.activeModel).Name);string next=string.Join(",",s.Meta.models)+s.Workshop.activeModel+s.Meta.tutorial+s.Workshop.reducedMotion;if(next==signature)return;signature=next;WorkshopUIFactory.Clear(rows);
   if(!string.IsNullOrEmpty(s.Meta.tutorial)){var art=WorkshopUIFactory.Node("Mira",rows,typeof(Image));WorkshopUIFactory.Size(art,150);art.GetComponent<Image>().sprite=Mira;art.GetComponent<Image>().preserveAspect=true;WorkshopUIFactory.Label("MiraExplanation",rows,s.Meta.tutorial=="lab"?"Mira: Hier entwickelst du fähigere KI-Modelle. 1.000 Erkenntnis für deine erste zufällige KI stehen bereit. Genau ein Modell ist aktiv; Sammlung und Upgrades bleiben beim Axiom erhalten.":"Mira: Dein neuer Axiomzyklus erhält Modelle, Forschung, Items und permanente Slots. Der INT-Zyklus beginnt neu. Axiome und Modellfähigkeiten helfen beim Wiederaufbau.",16,180);WorkshopUIFactory.Button("AcknowledgeMira",rows,"Verstanden",()=>game.Act(v=>{var n=v.Copy();n.Meta.tutorial="";return n;}));}
   var develop=WorkshopUIFactory.Button("DevelopModel",rows,"Zufällige KI entwickeln · "+MetaRules.ModelCost(s)+" Erkenntnis",Develop);develop.gameObject.SetActive(s.Meta.models.Any(l=>l<0));WorkshopUIFactory.Label("ModelPoolRule",rows,"Gleiche Chance je unbekanntem Modell · keine Duplikate · genau ein Modell aktiv",14,62);var deactivate=WorkshopUIFactory.Button("DeactivateModel",rows,"Kein Modell aktiv",()=>game.Act(v=>MetaRules.Select(v,null)));deactivate.interactable=game.Writable&&!ChallengeRules.Active(s);WorkshopUIFactory.Button("ModelMotion",rows,s.Workshop.reducedMotion?"Bewegung aus":"Bewegung an",()=>{Cancel();game.Act(v=>{var n=v.Copy();n.Workshop.reducedMotion=!n.Workshop.reducedMotion;n.Settings.effects=!n.Workshop.reducedMotion;return n;});});
   for(int i=0;i<MetaBalance.Models.Length;i++){int index=i;var m=MetaBalance.Models[i];var panel=WorkshopUIFactory.Vertical("model-"+m.Id,rows);var image=WorkshopUIFactory.Node("ModelArt",panel.transform,typeof(Image));WorkshopUIFactory.Size(image,76);image.GetComponent<Image>().sprite=ModelArt;image.GetComponent<Image>().preserveAspect=true;WorkshopUIFactory.Label("ModelTitle",panel.transform,m.Id+" · "+m.Name+"\n"+(s.Meta.models[i]<0?"Noch unbekannt":"Lv "+s.Meta.models[i]+" / "+MetaRules.ModelLimit(s)+(s.Workshop.activeModel==m.Id?" · AKTIV":"")),18,66);var preview=s.Copy();preview.Workshop.activeModel=m.Id;preview.Workshop.activeModelLevel=Math.Max(0,s.Meta.models[i]);WorkshopUIFactory.Label("ModelEffect",panel.transform,(m.Id=="K10"?"Universelle Slots: "+(preview.Workshop.activeModelLevel>=PrestigeRules.V("modelSlotsLevel")?2:1)+" · Itemboni ×"+(PrestigeRules.V("modelItemBase")+PrestigeRules.V("modelItemLevel")*preview.Workshop.activeModelLevel).ToString("F3"):"Primär: "+m.Kind+" ×"+(1+(m.Base-1)*(1+PrestigeRules.V("modelPrimaryLevel")*Math.Max(0,s.Meta.models[i]))).ToString("F3"))+"\nRevenue-Kern ×"+MetaRules.Core(preview).ToString("F3")+"\n"+(MetaRules.Level(s,"D06")>0?"Zweite Fähigkeit aktiv: ":"Mit D06: ")+m.Secondary,14,120);
    if(s.Meta.models[i]>=0){var choose=WorkshopUIFactory.Button("Select-"+m.Id,panel.transform,"Aktivieren",()=>game.Act(v=>MetaRules.Select(v,m.Id)));choose.interactable=game.Writable&&!ChallengeRules.Active(s)&&s.Workshop.activeModel!=m.Id;WorkshopUIFactory.Button("Upgrade-"+m.Id,panel.transform,"Level erhöhen · "+MetaRules.UpgradeCost(s,index)+" Erkenntnis",()=>game.Act(v=>MetaRules.Upgrade(v,m.Id)));}}
   UpdateAffordability();
  }
  void LateUpdate(){if(game!=null)UpdateAffordability();}
  void UpdateAffordability(){var s=game.State;var d=rows.Find("DevelopModel")?.GetComponent<Button>();if(d!=null)d.interactable=game.Writable&&!ChallengeRules.Active(s)&&s.Prestige.lab&&ScientificNumber.FromData(s.Prestige.knowledge).CompareTo(MetaRules.ModelCost(s))>=0;for(int i=0;i<10;i++){var b=rows.Find("model-"+MetaBalance.Models[i].Id+"/Upgrade-"+MetaBalance.Models[i].Id)?.GetComponent<Button>();if(b!=null)b.interactable=game.Writable&&!ChallengeRules.Active(s)&&s.Meta.models[i]<MetaRules.ModelLimit(s)&&ScientificNumber.FromData(s.Prestige.knowledge).CompareTo(MetaRules.UpgradeCost(s,i))>=0;}}
  void Develop(){var owned=(int[])game.State.Meta.models.Clone();if(game.Act(MetaRules.Develop)){int n=Enumerable.Range(0,10).First(i=>owned[i]<0&&game.State.Meta.models[i]>=0);pulse.Play("Entwickelt · "+MetaBalance.Models[n].Name,game.State.Workshop.reducedMotion);}}
  public void Cancel(){if(pulse!=null)pulse.Cancel();}void OnDisable(){Cancel();}void OnDestroy(){if(pulse!=null)Destroy(pulse.gameObject);}
 }
}
